                  yAxisId="left"
                  unit="%"
                  domain={[30, 80]}
                  tick={{ fontSize: 11 }}
                />
                <YAxis
                  yAxisId="right"
                  orientation="right"
                  domain={[20, 30]}
                  tick={{ fontSize: 11 }}
