                />
                <Tooltip />
                <Legend />
                <Bar yAxisId="left" dataKey="top1" name="Top-1 %" fill={COLORS.ocean} />
                <Bar yAxisId="left" dataKey="top3" name="Top-3 %" fill={COLORS.premier} />
                <Line
                  yAxisId="right"
                  type="monotone"
                  dataKey="hhi"
                  name="HHI/100"
                  stroke={COLORS.accent}
                  strokeWidth={2.5}
                  dot={{ r: 4 }}
                />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      ) : null}

      {panel === "fleet" ? (
        <ChartCard
          title="UNCTAD-style fleet backdrop"
