          </div>
        </ChartCard>
      ) : null}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
      {/* Keep ALLIANCE_SHARES referenced for tree-shake safety in QA imports */}
      <span className="hidden">{ALLIANCE_SHARES.length}</span>
    </div>
  );
}

