                      `${v}${name === "x" || name === "y" ? "%" : ""}`,
                      name === "x" ? "Share" : name === "y" ? "YoY" : "Size",
                    ]}
                    labelFormatter={(_, payload) =>
                      (payload?.[0]?.payload as { name?: string })?.name ?? ""
