            </div>
          </ChartCard>
        </div>
      ) : null}

      {panel === "path" ? (
        <ChartCard
          title={VIZ_MARKERS[4]}
          subtitle="Top-1 / top-3 alliance share and HHI/100 across the reshuffle"
        >
          <div className="h-[360px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%" minWidth={0}>
              <ComposedChart
