type Panel = "ladder" | "coast" | "carriers" | "path" | "fleet";
type Vintage = AllianceShareRow["vintage"];
type CarrierSort = "share" | "yoy" | "teu";

const COLORS = {
  ocean: "#0ea5e9",
  premier: "#2563eb",
  gemini: "#059669",
  msc: "#d97706",
  other: "#94a3b8",
  the_alliance: "#7c3aed",
  two_m: "#dc2626",
  accent: "#0f766e",
  muted: "#64748b",
  up: "#059669",
  down: "#dc2626",
};

const ALLIANCE_COLOR: Record<string, string> = {
  ocean: COLORS.ocean,
  premier: COLORS.premier,
  gemini: COLORS.gemini,
  msc: COLORS.msc,
  other: COLORS.other,
  the_alliance: COLORS.the_alliance,
  two_m: COLORS.two_m,
  independent: COLORS.other,
};

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
