                  layout="vertical"
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis type="number" unit="%" tick={{ fontSize: 11 }} />
                  <YAxis
                    type="category"
                    dataKey="label"
                    width={110}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v, _n, p) => [
                      `${Number(v)}% ?? ${fmtTeu((p.payload as AllianceShareRow).teu)} teu`,
                      "Share",
                    ]}
                  />
                  <Bar dataKey="sharePct" radius={[0, 4, 4, 0]}>
                    {allianceRows.map((r) => (
                      <Cell
                        key={r.id + r.vintage}
                        fill={ALLIANCE_COLOR[r.id] ?? COLORS.muted}
                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
          <ChartCard
            title="Mix donut"
            subtitle="Same vintage ?? click legend to isolate"
          >
            <div className="h-[320px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%" minWidth={0}>
                <PieChart>
                  <Pie
                    data={pieData}
                    dataKey="value"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    innerRadius={58}
                    outerRadius={100}
                    paddingAngle={2}
                    label={({ name, value }) =>
                      `${String(name).split(" ")[0]} ${value}%`
                    }
                  >
                    {pieData.map((d) => (
                      <Cell key={d.name} fill={d.fill} />
                    ))}
                  </Pie>
                  <Tooltip
                    formatter={(v, _n, p) => [
                      `${Number(v)}% (${fmtTeu((p.payload as { teu: number }).teu)} teu)`,
                      "Share",
                    ]}
                  />
                  <Legend />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      ) : null}

      {panel === "coast" ? (
        <ChartCard
          title={VIZ_MARKERS[2]}
          subtitle="Sea-Intelligence-style coast lens (carried) ??? Ocean still leads both gates"
        >
          <div className="h-[360px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%" minWidth={0}>
              <BarChart
                data={coastChart}
                margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="coast" tick={{ fontSize: 12 }} />
                <YAxis unit="%" tick={{ fontSize: 11 }} />
                <Tooltip />
                <Legend />
                <Bar dataKey="Ocean" stackId="a" fill={COLORS.ocean} />
                <Bar dataKey="Premier" stackId="a" fill={COLORS.premier} />
                <Bar dataKey="Gemini" stackId="a" fill={COLORS.gemini} />
                <Bar dataKey="MSC" stackId="a" fill={COLORS.msc} />
                <Bar dataKey="Other" stackId="a" fill={COLORS.other} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      ) : null}

      {panel === "carriers" ? (
        <div className="grid gap-4 lg:grid-cols-2">
          <ChartCard
            title={VIZ_MARKERS[3]}
            subtitle={`Sorted by ${carrierSort} ?? color = alliance`}
          >
            <div className="h-[360px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%" minWidth={0}>
                <BarChart
                  data={carrierChart}
                  layout="vertical"
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    tick={{ fontSize: 11 }}
                    domain={
                      carrierSort === "yoy" ? ["dataMin - 5", "dataMax + 5"] : [0, "auto"]
                    }
                  />
                  <YAxis
                    type="category"
                    dataKey="name"
                    width={88}
                    tick={{ fontSize: 10 }}
                  />
                  <Tooltip
                    formatter={(v, name) => [
                      String(name) === "yoyPct"
                        ? `${Number(v)}% YoY`
                        : String(name) === "sharePct"
                          ? `${Number(v)}%`
                          : fmtTeu(Number(v)),
                      String(name) === "yoyPct"
                        ? "YoY"
                        : String(name) === "sharePct"
                          ? "Share"
                          : "TEU",
                    ]}
                  />
                  <Bar
                    dataKey={
                      carrierSort === "yoy"
                        ? "yoyPct"
                        : carrierSort === "teu"
                          ? "teu"
                          : "sharePct"
                    }
                    radius={[0, 4, 4, 0]}
                  >
                    {carrierChart.map((r) => (
                      <Cell
                        key={r.name}
                        fill={
                          carrierSort === "yoy"
                            ? r.yoyPct >= 0
                              ? COLORS.up
                              : COLORS.down
                            : r.fill
                        }
                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
          <ChartCard
            title="Share ?? YoY scatter"
            subtitle="Bubble size ??? absolute TEU ?? Yang Ming ???30% is pooling, not exit"
