"use client";

import { useMemo, useState } from "react";
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  Tooltip,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import {
  ALLIANCE_SHARES,
  ANALYTICS,
  CARRIER_LADDER,
  COAST_SPLIT,
  CONCENTRATION_PATH,
  FLEET_CONTEXT,
  HEADLINE,
  SOURCE_NOTE,
  VIZ_MARKERS,
  allianceSharesForVintage,
  type AllianceShareRow,
} from "@/data/alliance-capacity-share-on-transpacific-2026-data";

type Panel = "ladder" | "coast" | "carriers" | "path" | "fleet";
type Vintage = AllianceShareRow["vintage"];
type CarrierSort = "share" | "yoy" | "teu";

const COLORS = {
  ocean: "#0ea5e9",
  premier: "#2563eb",
  gemini: "#059669",
  msc: "#d97706",
  other: "#94a3b8",
  the_alliance: "#7c3aed",
  two_m: "#dc2626",
  accent: "#0f766e",
  muted: "#64748b",
  up: "#059669",
  down: "#dc2626",
};

const ALLIANCE_COLOR: Record<string, string> = {
  ocean: COLORS.ocean,
  premier: COLORS.premier,
  gemini: COLORS.gemini,
  msc: COLORS.msc,
  other: COLORS.other,
  the_alliance: COLORS.the_alliance,
  two_m: COLORS.two_m,
  independent: COLORS.other,
};

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle ? <p className="mt-1 text-sm text-slate-500">{subtitle}</p> : null}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function fmtTeu(n: number): string {
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(2)}M`;
  if (n >= 1_000) return `${(n / 1_000).toFixed(0)}k`;
  return String(n);
}

