    [allianceRows],
  );

  const coastChart = useMemo(
    () =>
      COAST_SPLIT.map((c) => ({
        coast: c.label.replace("Asia ??? ", ""),
        Ocean: c.oceanPct,
        Premier: c.premierPct,
        Gemini: c.geminiPct,
        MSC: c.mscPct,
        Other: c.otherPct,
      })),
    [],
  );

  const carrierChart = useMemo(() => {
    const rows = [...CARRIER_LADDER].filter((c) => c.carrier !== "ZIM + other");
    rows.sort((a, b) => {
      if (carrierSort === "yoy") return b.yoyPct - a.yoyPct;
